from pathlib import Path


def reorder(value: int) -> str:
    bits = f"{value:08b}"
    return bits[6] + bits[7] + bits[4] + bits[5] + bits[2] + bits[3] + bits[0] + bits[1]


map_lines = "\n".join(f"        0x{reorder(v).replace('0', '8').replace('1', 'E')}," for v in range(256))

Path("BitPattern.h").write_text(f"""\
// This file was generated by {Path(__file__).name}

#ifndef BIT_PATTERN_H
#define BIT_PATTERN_H

#include <stdint.h>

typedef struct {{
    uint32_t green;
    uint32_t red;
    uint32_t blue;
}} __attribute__((__packed__)) BitPattern;

static inline __attribute__((always_inline)) BitPattern BitPatternFrom(const uint8_t red, const uint8_t green, const uint8_t blue) {{
    static const uint32_t map[] = {{
{map_lines}
    }};
    const BitPattern bitPattern = {{
        .green = map[green],
        .red = map[red],
        .blue = map[blue],
    }};
    return bitPattern;
}}

#endif
""")
